// Classic function
function calculateVelocity(speed, boost) {
  return speed * boost;
}

// Arrow function
const warpSync = (factor) => factor > 10 ? 'WARP' : 'STABLE';

// Default parameters
const launchMission = (planet = 'Mars', crew = 3) => {
  return `Launching to ${planet} with ${crew} crew.`;
};

const threatLevel = 7;

if (threatLevel >= 8) {
  console.log('CRITICAL ALERT');
} else if (threatLevel >= 5) {
  console.log('ELEVATED RISK');
} else {
  console.log('NOMINAL STATUS');
}

// Ternary shorthand
const status = fuelLevel > 50 ? 'ADEQUATE' : 'CRITICAL';

// Switch case
switch(sector) {
  case 'Alpha': console.log('Alpha Online'); break;
  case 'Beta': console.log('Beta Online'); break;
  default: console.log('Unknown Sector');
}

const crew = ['Jesmon', 'Astra', 'Nova'];
console.log(crew[0]);       // 'Jesmon'
crew.push('Zenith');        // Add to end
crew.splice(1, 1);          // Remove 1 at index 1

const vessel = {
  code: 'JES-007',
  speed: 12,
  crew: ['Jesmon', 'Nova']
};
console.log(vessel.speed);  // 12
vessel.fuel = 98;           // Add new property

const sectors = [1, 2, 3, 4, 5];

// Classic for loop
for (let i = 0; i < sectors.length; i++) {
  console.log('Sector', sectors[i]);
}

// Higher-order methods
const doubled = sectors.map(s => s * 2);    // [2,4,6,8,10]
const evens = sectors.filter(s => s % 2 === 0); // [2,4]
const total = sectors.reduce((sum, s) => sum + s, 0); // 15

// Select elements
const btn = document.querySelector('#launchBtn');
const panel = document.querySelector('.status-panel');

// Modify content & styles
panel.textContent = 'SYSTEMS ONLINE';
panel.classList.add('active');
panel.style.borderColor = 'lime';

// Create and inject new element
const newLog = document.createElement('div');
newLog.textContent = 'LOG: Mission initiated.';
document.getElementById('logContainer').appendChild(newLog);

// Event listener
document.querySelector('#fireBtn').addEventListener('click', () => {
  console.log('Engines fired!');
});

// Fetch with async/await
async function loadMissionData() {
  try {
    const response = await fetch('/assets/data/missions.json');
    const data = await response.json();
    renderMissions(data);
  } catch (error) {
    console.error('Uplink failed:', error);
  }
}
